# Tables
main=a[a.spec=='possessions_main'].copy();main['Forest [95% CI]']=main.apply(ci,axis=1);b=fe[fe.spec=='possessions_main'].copy();b['School FE [95% CI]']=b.apply(ci,axis=1)
