x=cv.copy();x['Weighted share of all Armenian students (%)']=(100*x.weight_share_all_ARM).round(1);x['Overlap effective N']=x.overlap_neff.round().astype(int);coverage=table(mapped(x[['spec','n','n9','n10','schools','Weighted share of all Armenian students (%)','Overlap effective N']]).rename(columns={'n':'Students','n9':'Grade 9','n10':'Grade 10','schools':'Schools'}))
x=ct[ct.family.isin(['primary','parental'])].copy();x['High − low [95% CI]']=x.apply(ci,axis=1);x['Holm p']=x.p_holm.round(3);contrast_table=table(mapped(x[['spec','domain','moderator','High − low [95% CI]','Holm p']]))
x=g.copy();x['Estimate [95% CI]']=x.apply(ci,axis=1);x=x.merge(sp[['spec','moderator','group','n','n9','n10','schools','adequate']],on=['spec','moderator','group']);group_table=table(mapped(x[['spec','domain','moderator','group','n','n9','n10','schools','adequate','Estimate [95% CI]']]))
x=var.copy();x['Mean score']=x['mean'].round(1);x['Between-school variance share (%)']=(100*x.between_share).round(1);x['sample']=x['sample'].map({'full_ARM':'Full Armenian PISA sample','overlap_sample':'Main overlap sample'});variance_table=table(mapped(x[['sample','domain','Mean score','Between-school variance share (%)']]))
levels_table=table(mapped(lev.round({'mean':1})).rename(columns={'mean':'Mean achievement'}))
x=bal.assign(abs_smd=bal.smd.abs()).groupby(['spec','weighting']).agg(max_abs_smd=('abs_smd','max'),above_01=('abs_smd',lambda s:sum(s>.1))).reset_index();x['max_abs_smd']=x.max_abs_smd.round(3);balance_table=table(mapped(x))
