ix=np.argsort(main.p.to_numpy());vals=np.maximum.accumulate((3-np.arange(3))*main.p.to_numpy()[ix]).clip(0,1);pp=np.empty(3);pp[ix]=vals;main['p_holm_domains']=pp;main.to_csv(O/'main_domain_tests.csv',index=False)
